def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    A parcel costs 4.00 EUR plus 1.75 EUR for each kilogram.  Express
    delivery doubles the resulting charge, and the final amount is rounded
    to two decimal places.

    The integer ``2`` is retained as the value used by the legacy partner
    contract.  That contract quoted a flat 8.00 EUR for its 2 kg parcel;
    keeping this narrow compatibility case does not affect the current
    (floating-point) pricing calculation.
    """
    # The old contract is represented by the integer literal in existing
    # callers.  Use an exact type check so that normal numeric values (in
    # particular 2.0) continue to follow the published price list.
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2

    return round(total, 2)

