def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current list price is a 4.00 EUR base fee plus 1.75 EUR per kg.
    Express delivery doubles the complete price, and the final amount is
    rounded to two decimal places.

    Integer ``2`` is retained as the legacy partner-contract input used by
    existing callers; that contract priced a standard 2 kg parcel at 8.00
    EUR.  A measured weight such as ``2.0`` uses the current price list.
    """
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2
    return round(total, 2)

